-- ============================================================
-- 医院个人科研成果诚信综合评价系统 · 初始化业务数据
-- 说明：
--   1. 本脚本在系统完成首次部署（数据库已初始化）后执行，用于填充
--      科室、人员、成果、风控工单等基础业务数据，供系统上线试运行与演示。
--   2. 脚本幂等：重复执行会先清理本脚本创建的数据段（dept_id>=100、
--      user_id>=200、ach_id 1001-1999、bl_id/risk_id/check_id/violation_id/appeal_id/notice_id 段）。
--   3. 年度诚信评价（research_integrity 汇总与明细）由系统"年度评价计算"
--      自动生成，无需手工写入；导入后在"评价管理"触发计算即可。
-- 初始密码：普通人员 123456；科研科/委员会/院领导 666888（登录后请修改）
-- ============================================================
USE `integrity_db`;

-- ---------- 幂等清理（仅清理本脚本数据段） ----------
DELETE FROM `research_notice` WHERE user_id >= 200 OR notice_id BETWEEN 1 AND 999;
DELETE FROM `research_appeal` WHERE user_id >= 200;
DELETE FROM `research_check_record` WHERE check_id BETWEEN 1 AND 999;
DELETE FROM `research_violation` WHERE user_id >= 200 OR violation_id BETWEEN 1 AND 999;
DELETE FROM `research_check` WHERE user_id >= 200 OR check_id BETWEEN 1 AND 999;
DELETE FROM `research_risk_log` WHERE user_id >= 200 OR risk_id BETWEEN 1 AND 999;
DELETE FROM `research_blacklist` WHERE bl_id BETWEEN 1 AND 999;
DELETE FROM `research_achievement` WHERE user_id >= 200 OR ach_id BETWEEN 1000 AND 1999;
DELETE FROM `sys_user_role` WHERE user_id >= 200;
DELETE FROM `sys_user` WHERE user_id >= 200;
DELETE FROM `sys_dept` WHERE dept_id >= 100;

